import json
with open('worker_code_pipeline-dry-run-72b-zs_20260519T192708.log') as f:
    lines = f.readlines()

# Print last 4 events (238-242)
for i in range(238, min(243, len(lines))):
    line = lines[i].strip()
    if not line:
        continue
    try:
        obj = json.loads(line)
    except:
        print(f'Line {i}: (not JSON)')
        continue
    tp = obj.get('type', '?')
    if tp == 'assistant':
        msg = obj.get('message', {})
        content = msg.get('content', [])
        stop = msg.get('stop_reason')
        print(f'Line {i}: type=assistant, stop_reason={stop}, content_types={[b.get(\"type\") for b in content if isinstance(b, dict)]}')
        for b in content:
            if isinstance(b, dict) and b.get('type') == 'text':
                t = b.get('text', '')
                print(f'  text ({len(t)} chars): {t[:300]!r}')
            elif isinstance(b, dict) and b.get('type') == 'tool_use':
                print(f'  tool_use: {b.get(\"name\")}')
    elif tp == 'result':
        print(f'Line {i}: type=result, result_len={len(obj.get(\"result\", \"\"))}, session_id={obj.get(\"session_id\", \"?\")[:20]}')
    elif tp == 'user':
        content = obj.get('message', {}).get('content', [])
        types = [b.get('type') for b in content if isinstance(b, dict)]
        print(f'Line {i}: type=user, content_types={types}')
    else:
        print(f'Line {i}: type={tp}')
